  function renderSourcePolicy():void{const allowed=Array.isArray((sourcePolicy as any).allowed_extensions)?(sourcePolicy as any).allowed_extensions:[];sourcePolicyInfo.textContent=allowed.length?`Formatos permitidos por policy: ${allowed.join(', ')}. La policy solo limita formatos; el árbol de propuesta debe justificar ruta, responsabilidad y contenido desde Architecture/Story.`:'Policy de extensiones pendiente.';}
  function renderUnifiedSourceTree():void{
    sourceList.replaceChildren();
    type TreeEntry={path:string;state:'SOURCE'|'PROPOSAL'|'DRAFT'|'CONFLICT';detail:string;open:()=>void};
    const byPath=new Map<string,TreeEntry>();
    for(const row of sourceRowsCache){byPath.set(row.relative_path,{path:row.relative_path,state:'SOURCE',detail:row.language_hint,open:()=>void openSource(row)});}
    if(implementationProposal?.status==='PROPOSED'){
      for(const row of implementationProposal.files){if(!byPath.has(row.target_path))byPath.set(row.target_path,{path:row.target_path,state:'PROPOSAL',detail:`${row.artifact_role??'artifact'} · ${row.docstring_summary??'review required'}`,open:()=>openProposalFile(row)});}
    }
    for(const row of draftSet){if(!byPath.has(row.target_path)||row.status==='CONFLICT')byPath.set(row.target_path,{path:row.target_path,state:row.status==='CONFLICT'?'CONFLICT':'DRAFT',detail:`${row.operation} · runtime-only`,open:()=>selectDraft(row)});else if(row.status==='DRAFT')byPath.set(row.target_path,{path:row.target_path,state:'DRAFT',detail:`${row.operation} · runtime-only`,open:()=>selectDraft(row)});}
    if(!byPath.size){const p=document.createElement('p');p.className='muted';p.textContent=storyStatus==='IN_PROGRESS'?'Source tree vacío. Usa «Proponer implementación desde contexto» para que DevPilot derive un árbol virtual reviewable desde StoryContextPack + Architecture; Manual CREATE queda como override.':'No hay source allowlisted. Activa primero una Story READY antes de autoría.';sourceList.append(p);return;}
    const root=new Map<string,any>();
    for(const entry of [...byPath.values()].sort((a,b)=>a.path.localeCompare(b.path))){let node=root;const parts=entry.path.split('/').filter(Boolean);parts.forEach((part,index)=>{if(index===parts.length-1){node.set(part,entry);return;}let child=node.get(part);if(!(child instanceof Map)){child=new Map<string,any>();node.set(part,child);}node=child;});}
    const renderNode=(node:Map<string,any>,container:HTMLElement):void=>{for(const [name,value] of [...node.entries()].sort(([a],[b])=>a.localeCompare(b))){if(value instanceof Map){const details=document.createElement('details');details.open=true;details.className='code-source-tree-dir';const summary=document.createElement('summary');summary.textContent=`📁 ${name}`;const children=document.createElement('div');children.className='code-source-tree-children';details.append(summary,children);container.append(details);renderNode(value,children);}else{const entry=value as TreeEntry;const b=button(name);b.className='code-source-item';b.dataset.sourcePath=entry.path;b.dataset.sourceState=entry.state;b.setAttribute('aria-label',`${entry.state} · ${entry.path}`);b.title=`${entry.state} · ${entry.path} · ${entry.detail}`;b.addEventListener('click',entry.open);container.append(b);}}};
    renderNode(root,sourceList);
  }
