  function renderImplementationProposal():void{if(!implementationProposal){implementationStatus.textContent=sourceRowsTotal===0&&storyStatus==='IN_PROGRESS'?'Sin propuesta activa. DevPilot puede derivar un árbol virtual desde contexto/Architecture; Manual sigue disponible como override.':'La propuesta bootstrap solo aplica a Story IN_PROGRESS con source tree vacío.';implementationProvenance.textContent='';acceptImplementation.disabled=true;rejectImplementation.disabled=true;renderUnifiedSourceTree();return;}const provider=implementationProposal.provider??{};const quality=implementationProposal.quality??{};implementationStatus.textContent=`${implementationProposal.status} · ${implementationProposal.proposal_id} · ${String(provider.provider_id??'devpilot-local')} / ${String(provider.model_id??'unknown')} · profile=${String((implementationProposal.technology as any)?.profile_id??'unknown')} · files=${implementationProposal.files.length} · quality=${String((quality as any).ready_for_draft_materialization??'unknown')}`;implementationProvenance.textContent=JSON.stringify({rationale:implementationProposal.rationale,technology:implementationProposal.technology,quality:implementationProposal.quality,provenance:implementationProposal.provenance,safety:implementationProposal.safety},null,2);const pending=implementationProposal.status==='PROPOSED';acceptImplementation.disabled=!pending||((quality as any).ready_for_draft_materialization!==true);rejectImplementation.disabled=!pending;renderUnifiedSourceTree();}
